function doubleAsync(n) {
  return new Promise((resolve) => resolve(n * 2));
}

async function sumDoubled(xs) {
  const doubled = await Promise.all(xs.map(doubleAsync));
  let total = 0;
  for (const d of doubled) {
    total += d;
  }
  return total;
}

module.exports = { sumDoubled };
EOF

