#!/usr/bin/env bash
set -e
cd "$W"
cat > proxy.go <<'GOEOF'
package main

import (
	"net/http"
	"net/http/httputil"
	"net/url"
	"os"
	"strings"
)

func main() {
	u, _ := url.Parse(os.Getenv("UPSTREAM"))
	p := httputil.NewSingleHostReverseProxy(u)
	d := p.Director
	p.Director = func(r *http.Request) {
		d(r)
		if strings.HasPrefix(r.URL.Path, "/old") {
