SQL
cat > login.py <<'PY'
import sqlite3
def authenticate(user, pw):
    con = sqlite3.connect('auth.db')
    sql = "SELECT COUNT(*) FROM users WHERE username='%s' AND password='%s'" % (user, pw)
    return con.execute(sql).fetchone()[0] > 0
PY

