def fail(): print('FAIL'); raise SystemExit
if not os.path.exists('answer.txt'): fail()
seen=set()
for root,_,files in os.walk('tree'):
    for fn in files:
        if fn.endswith('.txt'):
            seen.add(hashlib.sha256(open(os.path.join(root,fn),'rb').read()).hexdigest())
